/**
 * Deterministic hashing used for the persisted selection lottery.
 *
 * The lottery value for a member is a pure function of (seed, member id), so
 * regenerating with the same seed never re-rolls ties, and adding or removing
 * other candidates does not change an individual member's lottery number.
 */

/** FNV-1a 32-bit hash of a string. */
export function fnv1a32(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

/** Mixes a 32-bit value (murmur3 fmix) to improve distribution. */
function fmix32(h: number): number {
  h ^= h >>> 16;
  h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

/** Stable lottery number in [0, 1) for a member under a given seed. */
export function lotteryValue(seed: string, memberId: string): number {
  const h = fmix32(fnv1a32(`${seed}�${memberId}`));
  return h / 0x100000000;
}

/** Creates a new random seed string. Not used inside the engine itself. */
export function newSeed(random: () => number = Math.random): string {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let out = '';
  for (let i = 0; i < 16; i++) out += alphabet[Math.floor(random() * alphabet.length)];
  return out;
}
